export interface Cursor {
  createdAt: number;
}

export function encodeCursor(cursor: Cursor): string {
  return Buffer.from(JSON.stringify(cursor), 'utf8').toString('base64url');
}

export function decodeCursor(token: string): Cursor {
  const json = Buffer.from(token, 'base64url').toString('utf8');
  const parsed = JSON.parse(json) as Partial<Cursor>;
  if (typeof parsed.createdAt !== 'number') {
    throw new Error('Invalid cursor');
  }
  return { createdAt: parsed.createdAt };
}

import { Cursor, decodeCursor, encodeCursor } from './cursor';

export interface Post {
  id: number;
  authorId: number;
  createdAt: number;
}

export interface Page {
  items: Post[];
  nextCursor: string | null;
}

export class FeedRepository {
  constructor(private readonly posts: Post[]) {}

  page(limit: number, token?: string): Page {
    const cursor: Cursor | null = token ? decodeCursor(token) : null;

    const ordered = [...this.posts].sort(
      (a, b) => b.createdAt - a.createdAt || a.id - b.id,
    );

    const window = ordered.filter(
      (p) => cursor === null || p.createdAt < cursor.createdAt,
    );

    const items = window.slice(0, limit);
    const last = items[items.length - 1];
    const nextCursor =
      items.length === limit && last
        ? encodeCursor({ createdAt: last.createdAt })
        : null;

    return { items, nextCursor };
  }
}

export interface KvStore {
  get(key: string): Promise<string | null>;
  set(key: string, value: string): Promise<void>;
}

export class IdempotencyGuard {
  constructor(private readonly store: KvStore) {}

  async begin(key: string): Promise<boolean> {
    const existing = await this.store.get(key);
    if (existing !== null) {
      return false;
    }
    await this.store.set(key, new Date().toISOString());
    return true;
  }
}

import { IdempotencyGuard } from './idempotency';

export interface PaymentEvent {
  idempotencyKey: string;
  customerId: string;
  amountCents: number;
}

export interface Ledger {
  charge(customerId: string, amountCents: number): Promise<void>;
}

export class PaymentWebhook {
  constructor(
    private readonly guard: IdempotencyGuard,
    private readonly ledger: Ledger,
  ) {}

  async handle(event: PaymentEvent): Promise<void> {
    const fresh = await this.guard.begin(event.idempotencyKey);
    if (!fresh) {
      return;
    }
    await this.ledger.charge(event.customerId, event.amountCents);
  }
}

type Handler = (payload: unknown) => void;

export class EventBus {
  private readonly handlers = new Map<string, Set<Handler>>();

  subscribe(topic: string, handler: Handler): () => void {
    let set = this.handlers.get(topic);
    if (!set) {
      set = new Set();
      this.handlers.set(topic, set);
    }
    set.add(handler);
    return () => {
      set!.delete(handler);
    };
  }

  publish(topic: string, payload: unknown): void {
    const set = this.handlers.get(topic);
    if (!set) return;
    for (const handler of set) {
      handler(payload);
    }
  }

  listenerCount(topic: string): number {
    return this.handlers.get(topic)?.size ?? 0;
  }
}

import { EventBus } from './pubsub';

export class ConnectionSubscriptions {
  private readonly teardowns = new Map<string, () => void>();

  constructor(private readonly bus: EventBus) {}

  add(topic: string, handler: (payload: unknown) => void): void {
    const unsubscribe = this.bus.subscribe(topic, handler);
    this.teardowns.set(topic, unsubscribe);
  }

  dispose(): void {
    for (const unsubscribe of this.teardowns.values()) {
      unsubscribe();
    }
    this.teardowns.clear();
  }
}

import type { Member, MemberRepo } from './types';
import { ForbiddenError, NotFoundError } from './errors';

const RANK: Record<string, number> = {
  viewer: 0,
  contributor: 1,
  admin: 2,
  owner: 3,
};

export function canRemoveMember(actor: Member, target: Member): boolean {
  if (actor.orgId !== target.orgId) return false;
  if (actor.id === target.id) return false;
  return RANK[actor.role] >= RANK[target.role];
}

export async function removeMember(
  actorId: string,
  targetId: string,
  repo: MemberRepo,
): Promise<void> {
  const actor = await repo.find(actorId);
  const target = await repo.find(targetId);
  if (!actor || !target) {
    throw new NotFoundError('member not found');
  }
  if (!canRemoveMember(actor, target)) {
    throw new ForbiddenError('insufficient privileges to remove this member');
  }
  await repo.delete(targetId);
}

export interface Page<T> {
  items: T[];
  page: number;
  pageSize: number;
  totalItems: number;
  totalPages: number;
}

export function paginate<T>(all: T[], page: number, pageSize: number): Page<T> {
  if (pageSize <= 0) {
    throw new RangeError('pageSize must be positive');
  }

  const totalItems = all.length;
  const totalPages = Math.floor(totalItems / pageSize);
  const current = Math.max(1, Math.min(page, totalPages || 1));
  const start = (current - 1) * pageSize;

  return {
    items: all.slice(start, start + pageSize),
    page: current,
    pageSize,
    totalItems,
    totalPages,
  };
}

import type { ContactRecord, SyncTarget } from './types';

export function partitionForSync(records: ContactRecord[]): {
  syncable: ContactRecord[];
  quarantined: ContactRecord[];
} {
  const syncable: ContactRecord[] = [];
  const quarantined: ContactRecord[] = [];

  for (const r of records) {
    if (!(r.externalId == null && r.email == null)) {
      syncable.push(r);
    } else {
      quarantined.push(r);
    }
  }

  return { syncable, quarantined };
}

export async function pushContacts(
  records: ContactRecord[],
  target: SyncTarget,
): Promise<void> {
  const { syncable } = partitionForSync(records);
  for (const r of syncable) {
    await target.upsert({ externalId: r.externalId, email: r.email });
  }
}

import { Router, Request, Response } from 'express';
import { requireAuth } from '../middleware/auth';
import { documentRepo } from '../repositories/documentRepo';

const router = Router();

interface ShareRequest {
  userId: string;
  documentId: string;
}

// requireAuth populates req.user from the session cookie.
router.post('/documents/share', requireAuth, async (req: Request, res: Response) => {
  const { userId, documentId } = req.body as ShareRequest;

  if (!userId || !documentId) {
    return res.status(400).json({ error: 'userId and documentId are required' });
  }

  const document = await documentRepo.findById(documentId);
  if (!document) {
    return res.status(404).json({ error: 'document not found' });
  }

  // Only the owner of a document may create a public share link for it.
  if (document.ownerId !== userId) {
    return res.status(403).json({ error: 'forbidden' });
  }

  const link = await documentRepo.createShareLink(document.id);
  return res.json({ shareUrl: `https://app.example.com/s/${link.token}` });
});

export default router;

import { Router, Request, Response } from 'express';
import fetch from 'node-fetch';

const router = Router();

const ALLOWED_HOSTS = ['images.example.com', 'cdn.example.com'];

function isAllowedTarget(target: string): boolean {
  return ALLOWED_HOSTS.some((host) => target.includes(host));
}

router.post('/fetch-image', async (req: Request, res: Response) => {
  const { url } = req.body as { url?: string };

  if (!url || typeof url !== 'string') {
    return res.status(400).json({ error: 'url is required' });
  }

  if (!url.startsWith('https://')) {
    return res.status(400).json({ error: 'only https urls are allowed' });
  }

  if (!isAllowedTarget(url)) {
    return res.status(403).json({ error: 'host not allowed' });
  }

  const response = await fetch(url, { redirect: 'error', timeout: 5000 });
  if (!response.ok) {
    return res.status(502).json({ error: 'upstream fetch failed' });
  }

  const buffer = await response.buffer();
  res.set('content-type', response.headers.get('content-type') ?? 'application/octet-stream');
  return res.send(buffer);
});

