import { Router, Request, Response } from 'express';
import * as path from 'path';
import * as fs from 'fs/promises';

const router = Router();

const REPORTS_DIR = path.resolve(__dirname, '../../storage/reports');

router.post('/reports/download', async (req: Request, res: Response) => {
  const { file } = req.body as { file?: string };

  if (!file || typeof file !== 'string') {
    return res.status(400).json({ error: 'file is required' });
  }

  // Reject traversal sequences and absolute paths.
  if (file.includes('..') || file.startsWith('/') || file.includes('\\')) {
    return res.status(400).json({ error: 'invalid file name' });
  }

  const name = decodeURIComponent(file);
  const target = path.join(REPORTS_DIR, name);

  try {
    const data = await fs.readFile(target);
    res.set('content-type', 'application/pdf');
    return res.send(data);
  } catch {
    return res.status(404).json({ error: 'report not found' });
  }
});

