export interface Row {
  id: string;
  score: number;
}

export interface Page {
  rows: Row[];
  nextCursor: string | null;
}

type Fetcher = (afterId: string | null, take: number) => Promise<Row[]>;

export class Feed {
  constructor(
    private readonly fetch: Fetcher,
    private readonly pageSize: number,
  ) {}

  async page(cursor: string | null): Promise<Page> {
    const take = this.pageSize + 1;
    const fetched = await this.fetch(cursor, take);

    const hasMore = fetched.length >= this.pageSize;
    const rows =
      fetched.length > this.pageSize
        ? fetched.slice(0, this.pageSize)
        : fetched;

    const nextCursor =
      hasMore && rows.length > 0 ? rows[rows.length - 1].id : null;

    return { rows, nextCursor };
  }
}

export type Sink<T> = (rows: readonly T[]) => Promise<void>;

export class BatchWriter<T> {
  private batch: T[] = [];

  constructor(
    private readonly sink: Sink<T>,
    private readonly flushAt: number = 100,
  ) {}

  async add(row: T): Promise<void> {
    this.batch.push(row);
    if (this.batch.length >= this.flushAt) {
      await this.sink(this.batch);
      this.batch = [];
    }
  }

  async flush(): Promise<void> {
    if (this.batch.length === 0) return;
    await this.sink(this.batch);
    this.batch = [];
  }

  get pending(): number {
    return this.batch.length;
  }
}

export interface Conn {
  query<T>(sql: string, params: unknown[]): Promise<T[]>;
  release(): void;
}

export interface Pool {
  acquire(): Promise<Conn>;
}

export interface Account {
  id: string;
  balance: number;
}

export class AccountStore {
  constructor(private readonly pool: Pool) {}

  async transfer(from: string, to: string, amount: number): Promise<void> {
    const conn = await this.pool.acquire();
    await conn.query('BEGIN', []);
    await conn.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, from],
    );
    await conn.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, to],
    );
    await conn.query('COMMIT', []);
    conn.release();
  }
}

export interface Config {
  timeoutMs?: number | null;
  retries?: number | null;
  baseUrl?: string | null;
}

export interface ResolvedConfig {
  timeoutMs: number;
  retries: number;
  baseUrl: string;
}

const DEFAULTS: ResolvedConfig = {
  timeoutMs: 5000,
  retries: 3,
  baseUrl: 'https://api.example.com',
};

function pick<T>(value: T | null | undefined, fallback: T): T {
  return value == null ? fallback : value;
}

export function resolveConfig(input: Config): ResolvedConfig {
  return {
    timeoutMs: pick(input.timeoutMs, DEFAULTS.timeoutMs),
    retries: pick(input.retries, DEFAULTS.retries),
    baseUrl: pick(input.baseUrl, DEFAULTS.baseUrl),
  };
}

export class RingBuffer<T> {
  private readonly buf: (T | undefined)[];
  private readonly mask: number;
  private head = 0;
  private count = 0;

  constructor(capacity: number) {
    if (capacity <= 0 || (capacity & (capacity - 1)) !== 0) {
      throw new Error('capacity must be a positive power of two');
    }
    this.buf = new Array<T | undefined>(capacity);
    this.mask = capacity - 1;
  }

  push(item: T): void {
    const idx = (this.head + this.count) & this.mask;
    if (this.count === this.buf.length) {
      this.head = (this.head + 1) & this.mask;
    } else {
      this.count += 1;
    }
    this.buf[idx] = item;
  }

  toArray(): T[] {
    const out: T[] = [];
    for (let i = 0; i < this.count; i += 1) {
      out.push(this.buf[(this.head + i) & this.mask] as T);
    }
    return out;
  }
}

export interface Fs {
  mkdir(path: string): Promise<void>;
  stat(path: string): Promise<{ isDirectory: boolean }>;
}

export class Workspace {
  constructor(
    private readonly fs: Fs,
    private readonly root: string,
  ) {}

  async ensure(relative: string): Promise<string> {
    const full = `${this.root}/${relative}`;

    try {
      await this.fs.mkdir(full);
    } catch {}

    const info = await this.fs.stat(full);
    if (!info.isDirectory) {
      throw new Error(`${full} exists but is not a directory`);
    }

    return full;
  }
}
